SELECT p.gender, a.admittime, a.dischtime, a.deathtime, a.los, p.ckd_status, p.diabetes_status, p.afib_status, p.hypertension_status, COUNT(a.deathtime)::FLOAT / NULLIF(COUNT(a.hadm_id), 0) AS mortality_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 75 AND 85 AND a.deathtime IS NOT NULL AND a.deathtime <= a.dischtime AND a.los <= 5 AND p.ckd_status IS NOT NULL AND p.diabetes_status IS NOT NULL AND p.afib_status IS NOT NULL AND p.hypertension_status IS NOT NULL AND (microbiologyevents.micro_specimen_id = 'S' OR microbiologyevents.micro_specimen_id = 'I') AND microbiologyevents.test_name != 'Shock' GROUP BY p.gender, a.admittime, a.dischtime, a.deathtime, a.los, p.ckd_status, p.diabetes_status, p.afib_status, p.hypertension_status ORDER BY p.gender, a.admittime, a.dischtime, a.deathtime, a.los, p.ckd_status, p.diabetes_status, p.afib_status, p.hypertension_status NULLS LAST;